vector<int> Tadd, Tmin;

void push(int v) {
    Tadd[2 * v + 1] += Tadd[v];
    Tadd[2 * v + 2] += Tadd[v];
    Tadd[v] = 0;
}

int getmin(int v) {
    return Tmin[v] + Tadd[v];
}

void upd(int v) {
    Tmin[v] = min(getmin(2 * v + 1), getmin(2 * v + 2));
}

void init(int v, int l, int r) {
    if (l + 1 == r) {
        Tmin[v] = -l;
        return;
    }
    int mid = (l + r) >> 1;
    init(2 * v + 1, l, mid);
    init(2 * v + 2, mid, r);
    upd(v);
}

void init(int n) {
    Tadd.assign(4 * n, 0);
    Tmin.resize(4 * n);
    init(0, 0, n);
}

void addVal(int v, int l, int r, int lf, int rg, int val) {
    if (l == lf && r == rg) {
        Tadd[v] += val;
        return;
    }
    int mid = (l + r) >> 1;
    push(v);
    if (lf < mid)
        addVal(2 * v + 1, l, mid, lf, min(mid, rg), val);
    if (rg > mid)
        addVal(2 * v + 2, mid, r, max(lf, mid), rg, val);
    upd(v);
}

int firstNeg(int v, int l, int r) {
    if (l + 1 == r) {
        assert(getmin(v) < 0);
        return l;
    }
    push(v);
    int mid = (l + r) >> 1;
    int ans = -1;
    if (getmin(2 * v + 1) < 0)
        ans = firstNeg(2 * v + 1, l, mid);
    else
        ans = firstNeg(2 * v + 2, mid, r);
    upd(v);
    return ans;
}

int calcDemand(int i) {
    return min(n, max(a[i] - ac, 0) + max(d[i] - dr, 0));
}

inline void solve() {
    init(n + 2);
    fore (i, 0, n) {
        int p = calcDemand(i);
        addVal(0, 0, n + 2, p + 1, n + 2, 1);
    }

    int m; cin >> m;
    fore (j, 0, m) {
        int k, na, nd;
        cin >> k >> na >> nd;
        k--;
        int p = calcDemand(k);
        addVal(0, 0, n + 2, p + 1, n + 2, -1);
        a[k] = na;
        d[k] = nd;
        p = calcDemand(k);
        addVal(0, 0, n + 2, p + 1, n + 2, 1);

        int ans = firstNeg(0, 0, n + 2);
        cout << ans - 1 << '\n';
    }
}

