#include <bits/stdc++.h>

using namespace std;

using li = long long;

const int N = 10;
const int LOG = 50;
const int LCM = 2520;

int n;
li m;
int a[N], b[N];
li go[LOG][N][LCM];

void solve() {
  cin >> n >> m;
  for (int i = 0; i < n; ++i) cin >> a[i];
  for (int i = 0; i < n; ++i) cin >> b[i];
  for (int x = 0; x < n; ++x) {
    for (int y = 0; y < LCM; ++y) {
      go[0][x][y] = ((y + 1) % a[x]) != b[x];
    }
  }
  for (int i = 1; i < LOG; ++i) {
    for (int x = 0; x < n; ++x) {
      for (int y = 0; y < LCM; ++y) {
        go[i][x][y] = go[i - 1][x][y] + go[i - 1][(x + (1LL << (i - 1))) % n][(y + go[i - 1][x][y]) % LCM];  
      }
    }
  }
  if (go[LOG - 1][0][0] < m) {
    cout << -1 << endl;
    return;
  }
  li s = 0, ans = 0;
  for (int i = LOG - 1; i >= 0; --i) {
    if (s + go[i][ans % n][s % LCM] < m) {
      s += go[i][ans % n][s % LCM];
      ans += 1LL << i;
    }
  }
  cout << ans + 1 << endl;
}

int main() {
  int t;
  cin >> t;
  while (t--) solve();
}

#include<bits/stdc++.h>

using namespace std;

int n, m, k;

const int N = 4043;
const int MOD = 998244353;

int add(int x, int y)
{
    x += y;
    while(x >= MOD) x -= MOD;
    while(x < 0) x += MOD;
    return x;
}   

int sub(int x, int y)
{
    return add(x, -y);
}

int mul(int x, int y)
{
    return (x * 1ll * y) % MOD;
}

int binpow(int x, int y)
{
    int z = 1;
    while(y > 0)
    {
        if(y % 2 == 1) z = mul(z, x);
        x = mul(x, x);
        y /= 2;
    }
    return z;
}

int fact[N];
int rfact[N];

void precalc_factorials()
{
    fact[0] = 1;
    for(int i = 1; i < N; i++)
        fact[i] = mul(fact[i - 1], i);
    for(int i = 0; i < N; i++)
        rfact[i] = binpow(fact[i], MOD - 2);
}

int choose(int x, int y)
{
    if(x < 0 || y < 0 || x < y) return 0;
    return mul(fact[x], mul(rfact[y], rfact[x - y]));
}

vector<int> prefix_sum(const vector<int>& a)
{
    int n = a.size();
    vector<int> p(n + 1);
    for(int i = 0; i < n; i++) p[i + 1] = add(a[i], p[i]);
    return p;
}

int get(const vector<int>& a, int i)
{
    if(a.size() > i) return a[i];
    else return a.back();
}   

int main()
{
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    int n, m, k;
    cin >> n >> m >> k;
    precalc_factorials();

    vector<vector<int>> A(k, vector<int>(n + m));
    for(int x = 0; x < k; x++)
    {
        vector<int> by_rows(n + 1);
        for(int i = 1; i <= n; i++)
            by_rows[i] = mul(choose(n, i), binpow(x, n - i));
        vector<int> pr = prefix_sum(by_rows);

        vector<int> by_cols(m + 1);
        for(int i = 1; i <= m; i++)
            by_cols[i] = mul(choose(m, i), binpow(x, m - i));
        vector<int> pc = prefix_sum(by_cols);

        for(int i = 1; i <= max(n, m); i++)
        {
            A[x][n + m - i] = sub(mul(get(pr, i + 1), get(pc, i + 1)), mul(get(pr, i), get(pc, i)));
        }     
    }

    for(int i = min(n, m); i < n + m; i++)
    {
        int ans = 0;
        for(int j = 0; j < k; j++)
        {
            int cur = mul(choose(k - 1, j), A[k - 1 - j][i]);
            if(j % 2 == 0)
                ans = add(ans, cur);
            else
                ans = add(ans, -cur);
        }
        cout << ans << " ";
    }
    cout << endl;
}
